const add=(id,name,group,unit,effect,indications,adverse,care,sources,adult,extra={})=>{DRUGS.push({id,name,group,unit,effect,indications,adverse,care,sources,profiles:{...(adult?{adult}:{} )},...extra});return DRUGS.at(-1);};
const nor=add('noradrenalina','Noradrenalina','Vasoativos','mcg','Predomínio α1: aumenta resistência vascular e pressão arterial.','Choque vasodilatador; hipotensão grave com hipoperfusão.','Isquemia, arritmias e necrose por extravasamento.','Prescrever em noradrenalina BASE. Confirmar equivalência do sal; acesso central preferido, linha dedicada e vigilância do sítio.',[dm('fd398152-b428-4dca-8478-b691b909ee0e')],infusion(1000,[P(4000,250,'SG 5%'),P(8000,250,'SG 5%'),P(16000,250,'SG 5%'),P(20000,200,'SG 5%')],[R('Titulação no choque',.05,1,'mcg/kg/min','Faixa de referência; não há teto universal. O PDF original cita até 3 mcg/kg/min em situações excepcionais.')],[]),{aliases:'Norepinefrina · Levophed',presentation:'Base 1 mg/mL; exemplo: 4 mg base/4 mL. O rótulo pode expressar o sal em quantidade diferente.'});
add('adrenalina','Adrenalina','Vasoativos','mcg','Agonista α e β: vasopressão, inotropismo e broncodilatação.','PCR, anafilaxia, choque e bradicardia refratária, com esquemas distintos.','Taquiarritmia, isquemia, hiperglicemia e elevação do lactato.','PCR usa solução 0,1 mg/mL; anafilaxia IM usa 1 mg/mL. Não intercambiar concentrações ou vias.',[dm('ef556382-9d19-4f0e-9dbe-fcecc772a3e2')],infusion(1000,[P(1000,100,'SG 5%'),P(4000,250,'SG 5%'),P(10000,100,'SG 5%')],[R('Choque séptico · bula',.05,2,'mcg/kg/min'),R('Bradicardia · ACLS',2,10,'mcg/min')],['aha'],{boluses:[B('PCR · a cada 3–5 min',1000,1000,'mcg',false,null,100,null,'1 mg IV/IO; usar 1 mg em 10 mL.',{preparation:'Se ampola 1 mg/mL: 1 mL + 9 mL de SF → 10 mL, 100 mcg/mL.'}),B('Anafilaxia · IM',300,500,'mcg',false,null,1000,null,'Face anterolateral da coxa; repetir em 5–15 min se necessário.',{route:'IM'})]}),{aliases:'Epinefrina',presentation:'1 mg/mL (1:1.000) e 0,1 mg/mL (1:10.000).'});
add('dobutamina','Dobutamina','Vasoativos','mcg','Inotrópico β1; aumenta débito, podendo reduzir resistência vascular.','Baixo débito com hipoperfusão; choque cardiogênico após avaliação da pressão e volemia.','Taquiarritmias, hipotensão e isquemia.','ECG, pressão e perfusão. Obstrução dinâmica da via de saída pode piorar.',[dm('9794e9d0-c8b7-4d18-8cd1-15cc4f2a9a55')],infusion(12500,[P(250000,250),P(500000,250),P(250000,50)],[R('Suporte inotrópico',2.5,20,'mcg/kg/min','Usual 2,5–15; doses maiores exigem reavaliação do benefício e arritmias.')],[]),{presentation:'250 mg/20 mL = 12,5 mg/mL; confirmar a ampola disponível.'});
add('dopamina','Dopamina','Vasoativos','mcg','Efeitos dopaminérgicos, β e α dependentes da dose.','Alternativa selecionada para hipotensão com bradicardia; não é preferência rotineira na sepse.','Arritmias, isquemia e extravasamento.','Não usar “dose renal” para proteção renal. Confirmar estoque: há apresentações de 5 e 40 mg/mL.',[dm('1f306ad2-3606-4525-5a8a-ce78f426c1a2')],infusion(5000,[P(250000,250,'SG 5%'),P(500000,250,'SG 5%'),P(200000,50,'SG 5%')],[R('Faixa usual',2,20,'mcg/kg/min'),R('Bradicardia · ACLS',5,20,'mcg/kg/min')],['aha']),{presentation:'Referência BR do arquivo: 50 mg/10 mL = 5 mg/mL. Selecionar a concentração real.'});
add('vasopressina','Vasopressina','Vasoativos','U','Vasoconstrição V1 e retenção de água via V2.','Adjuvante da noradrenalina no choque vasodilatador.','Isquemia periférica/mesentérica, hiponatremia e redução do débito.','Dose adulta usual fixa, não por kg. Acesso central; acompanhar sódio e perfusão.',[dm('e6666508-8192-10f8-e053-2995a90a530f')],infusion(20,[P(20,200),P(20,100),P(20,50),P(50,50)],[R('Adjuvante usual na sepse',.03,.03,'U/min'),R('Choque séptico · faixa da bula',.01,.07,'U/min','A faixa da bula não implica titulação rotineira até o máximo.')],['sepsis']),{presentation:'20 U/mL.',aliases:'Argipressina · Encrise'});
add('milrinona','Milrinona','Vasoativos','mcg','Inibidor PDE3: inotropismo e vasodilatação sistêmica/pulmonar.','Baixo débito, pós-operatório cardíaco; opção na disfunção de VD.','Hipotensão, arritmias e trombocitopenia.','Reduzir infusão na disfunção renal. Ataque pode piorar hipotensão; não é obrigatório no choque.',[dm('6c6b69f9-e229-4a93-a108-9eafdab614f0')],infusion(1000,[P(10000,50),P(20000,100),P(20000,50)],[R('Manutenção · função renal preservada',.375,.75,'mcg/kg/min')],[],{boluses:[B('Ataque opcional',50,50,'mcg',true,null,200,10,'Evitar em hipotensão importante; considerar esquema sem ataque.')]}),{presentation:'1 mg/mL = 1.000 mcg/mL.'});
add('levosimendana','Levosimendana','Vasoativos','mcg','Sensibiliza troponina ao cálcio e causa vasodilatação.','IC aguda grave em adulto quando suporte inotrópico é apropriado.','Hipotensão, taquicardia, hipocalemia e arritmias.','Contraindicado em ClCr <30 mL/min e disfunção hepática grave; não recomendado <18 anos. Ataque pode ser omitido na hipotensão.',[{label:'AEMPS · Simdax',url:'https://cima.aemps.es/cima/dochtml/ft/64154/FichaTecnica_64154.html'}],infusion(2500,[P(12500,500,'SG 5%'),P(25000,500,'SG 5%')],[R('Infusão por até 24 h',.05,.2,'mcg/kg/min','Início usual 0,1. Concentração ≤50 mcg/mL.')],[],{maxConcentration:50}),{presentation:'2,5 mg/mL = 2.500 mcg/mL; frasco 5 mL.',aliases:'Simdax'});
add('fenilefrina','Fenilefrina','Vasoativos','mcg','Agonista α1 sem inotropismo direto; eleva pós-carga.','Hipotensão perioperatória; situações selecionadas de vasodilatação com taquiarritmia.','Bradicardia reflexa, queda do débito e isquemia.','Concentrado 10 mg/mL exige diluição. Não é primeira escolha rotineira para sepse ou baixo débito.',[dm('c2ba1b3e-94bc-494d-b0fe-4ab9dd61dddc')],infusion(10000,[P(10000,500),P(10000,250)],[R('Hipotensão perioperatória',.5,1.4,'mcg/kg/min'),R('Choque vasodilatador · bula',.5,6,'mcg/kg/min')],[],{boluses:[B('Perioperatório',50,250,'mcg',false,null,100,null,'Titular; bolus de solução diluída 100 mcg/mL.',{preparation:'1 mL de 10 mg/mL + 99 mL SF = 100 mL, 100 mcg/mL.'})]}),{presentation:'Concentrado 10 mg/mL (10.000 mcg/mL); há soluções prontas diferentes.'});
add('angiotensina','Angiotensina II','Vasoativos','ng','Vasoconstritor do sistema renina–angiotensina.','Choque distributivo refratário a volume adequado e vasopressores.','Tromboembolismo, hipertensão e isquemia periférica.','Acesso central e profilaxia de TEV se possível. Não extrapolar para choque cardiogênico. Disponibilidade brasileira deve ser confirmada.',[{label:'SmPC · Giapreza',url:'https://www.medicines.org.uk/emc/product/13868/smpc'}],infusion(2500000,[P(2500000,500),P(5000000,500)],[R('Manutenção',1.25,40,'ng/kg/min'),R('Primeiras 3 h',1.25,80,'ng/kg/min','Início recomendado 20 ng/kg/min; limite inicial não se aplica à manutenção.')],[]),{presentation:'2,5 mg/mL = 2.500.000 ng/mL.',tag:'Disponibilidade a confirmar'});
add('isoprenalina','Isoprenalina','Vasoativos','mcg','Agonista β: aumenta frequência e contratilidade; vasodilata.','Ponte selecionada em bloqueio AV/bradicardia enquanto se organiza estimulação.','Taquiarritmia, isquemia e hipotensão.','Monitorização contínua. Evitar em isquemia ativa; não substitui marca-passo.',[{label:'NHS · Isoprenalina',url:'https://aaamedicines.org.uk/guidelines/resuscitation-and-anaphylaxis/isoprenaline-infusion-for-patients-with-heart-block-or-symptomatic-bradycardia/'}],infusion(200,[P(2000,500)],[R('Início · ponte para estimulação',1,null,'mcg/min','Titular à resposta; não há máximo universal neste esquema.')],[]),{aliases:'Isoproterenol',presentation:'0,2 mg/mL = 200 mcg/mL.',tag:'Uso selecionado'});
add('metaraminol','Metaraminol','Vasoativos','mg','Vasopressor simpaticomimético, predominantemente α.','Hipotensão perioperatória ou selecionada.','Hipertensão, arritmia e isquemia.','Titulação individual; não há faixa BIC universal na fonte. Confirmar disponibilidade e diluição.',[{label:'SmPC · Metaraminol',url:'https://www.medicines.org.uk/emc/product/14609/smpc'}],infusion(10,[P(15,500),P(100,500)],[],[],{boluses:[B('IV · conforme resposta',.5,5,'mg',false,null,1,null,'Diluição para 1 mg/mL; doses menores são preferíveis para titulação.',{preparation:'10 mg (1 mL) + 9 mL de SF = 10 mL, 1 mg/mL.'})],manualUnit:'mg/h'}),{presentation:'10 mg/mL.',tag:'Uso selecionado'});
add('efedrina','Efedrina','Vasoativos','mg','Simpaticomimético indireto/direto: eleva pressão e frequência.','Hipotensão relacionada à anestesia.','Taquicardia, arritmia e taquifilaxia.','Não usar como substituto de ressuscitação volêmica ou vasopressor contínuo no choque prolongado.',[dm('552c341b-4892-4dc7-8b9f-cb6be914b0d1')],bolus(50,[B('Hipotensão perioperatória',5,10,'mg',false,null,5,null,'Repetir à resposta; máximo total 50 mg na bula.',{preparation:'50 mg (1 mL) + 9 mL SF → 10 mL, 5 mg/mL.'})],[]),{presentation:'Exemplo de bula: 50 mg/mL. Confirmar apresentação BR.'});
add('terlipressina','Terlipressina','Vasoativos','mg','Análogo da vasopressina, com vasoconstrição esplâncnica.','Hemorragia varicosa e síndrome hepatorrenal em protocolo específico.','Isquemia, hiponatremia e insuficiência respiratória.','Não é vasopressor de escolha na sepse. Doses expressas como acetato não equivalem à mesma massa de base. Não iniciar em hipóxia.',[{label:'Ferring · Glypressin',url:'https://www.ferring.com.br/wp-content/uploads/sites/14/2023/06/BUL_GLY_SOL_LIO_FICSA_FLAS_VP_07_.pdf'}],{stock:.2,sources:[],reference:'Esquemas de HDA e síndrome hepatorrenal exigem diagnóstico, função orgânica e apresentação. Consultar bula vinculada; sem conversão automática entre acetato e base.'},{presentation:'Glypressin liofilizado 1 mg de acetato/5 mL após reconstituição; solução pronta tem concentração diferente.'});
add('nitroprussiato','Nitroprussiato de sódio','Vasodilatadores','mcg','Doador de NO: dilatação arterial e venosa, com redução rápida de pós-carga.','Emergência hipertensiva; situações selecionadas de falência cardíaca com pressão suficiente.','Hipotensão; toxicidade por cianeto/tiocianato.','Fotoproteção. Cautela renal/hepática. Dose de 10 mcg/kg/min apenas por tempo muito curto (até 10 min), nunca como manutenção usual.',[dm('a8c5d04b-c6cb-46e6-b90c-e858a0a52406')],infusion(25000,[P(50000,250,'SG 5%'),P(50000,500,'SG 5%'),P(50000,1000,'SG 5%')],[R('Titulação usual',.3,2,'mcg/kg/min'),R('Limite excepcional · até 10 min',.3,10,'mcg/kg/min','Reavaliar toxicidade e alternativa; a dose máxima não deve ser mantida.')],[]),{presentation:'50 mg, reconstituídos conforme fabricante; exemplo: 2 mL → 25 mg/mL.'});
add('nitroglicerina','Nitroglicerina','Vasodilatadores','mcg','Venodilatação predominante; reduz pré-carga e demanda miocárdica.','SCA com dor/hipertensão; edema pulmonar hipertensivo.','Hipotensão, cefaleia, tolerância e metemoglobinemia.','Evitar hipotensão, IAM de VD dependente de pré-carga e uso recente de PDE5 (sildenafila/vardenafila 24 h; tadalafila 48 h). Equipo adequado para evitar adsorção.',[dm('578d8159-5ec6-457f-b4a8-9add624d43a8')],infusion(5000,[P(25000,250,'SG 5%'),P(50000,250,'SG 5%'),P(50000,500,'SG 5%')],[R('Titulação · referência',5,200,'mcg/min','Dose fixa, não por kg. Faixa usual; não é teto universal. Esquemas de alta dose para SCAPE são off-label e exigem protocolo próprio.')],[]),{aliases:'Tridil',presentation:'5 mg/mL = 5.000 mcg/mL.'});
add('nicardipina','Nicardipina','Vasodilatadores','mg','Bloqueador de canal de cálcio arterial, titulável.','Emergência hipertensiva; controle pressórico neurológico.','Taquicardia, hipotensão, flebite e cefaleia.','Atenção à estenose aórtica importante e insuficiência cardíaca; monitorização de PA.',[dm('a3e33add-0d09-423a-9109-42e5ba7148d5')],infusion(2.5,[P(25,250),P(25,500)],[R('Adulto · IV',5,15,'mg/h','Aumentar 2,5 mg/h a cada 5–15 min conforme meta.')],[]),{presentation:'Exemplo: 25 mg/10 mL = 2,5 mg/mL; também há bolsas prontas.',tag:'Disponibilidade a confirmar'});
add('clevidipina','Clevidipina','Vasodilatadores','mg','Bloqueador de canal de cálcio arterial de ação ultracurta.','Controle pressórico IV titulável.','Hipotensão, taquicardia e carga lipídica.','Contraindicada em alergia a ovo/soja, distúrbio do metabolismo lipídico e estenose aórtica grave. Não diluir a emulsão.',[dm('f9290625-b723-4eda-bab8-a97bef6041f6')],infusion(.5,[P(25,50,'Sem diluição')],[R('Início',1,2,'mg/h'),R('Faixa usual',4,6,'mg/h'),R('Limite de curta duração',4,32,'mg/h','Experiência limitada a 32 mg/h; respeitar carga lipídica e volume máximo da bula em 24 h.')],[]),{presentation:'Emulsão 0,5 mg/mL.',tag:'Disponibilidade a confirmar'});
add('urapidil','Urapidil','Vasodilatadores','mg','Antagonista α1 e ação central: reduz resistência vascular.','Crise hipertensiva em cenários selecionados.','Hipotensão, náusea, tontura e cefaleia.','Reduzir em disfunção renal/hepática e idosos. Confirmar acesso ao medicamento no Brasil.',[{label:'AEMPS · Urapidil',url:'https://cima.aemps.es/cima/dochtml/ft/76741/FichaTecnica_76741.html'}],infusion(5,[P(250,500)],[R('Manutenção · referência',9,30,'mg/h','Titular à resposta; início rápido e manutenção são esquemas distintos.')],[]),{presentation:'5 mg/mL.',tag:'Disponibilidade a confirmar'});
