const dimensions={mg:'mass',mcg:'mass',ng:'mass',U:'activity',mU:'activity',mEq:'charge',mmol:'amount'};
const factors={mg:1,mcg:.001,ng:.000001,U:1,mU:.001,mEq:1,mmol:1};
export function number(value){if(typeof value==='number')return Number.isFinite(value)&&value>=0?value:null;const s=String(value??'').trim();if(!/^\d+(?:[.,]\d+)?$/.test(s))return null;const n=Number(s.replace(',','.'));return Number.isFinite(n)?n:null;}
export function convert(value,from,to){if(dimensions[from]!==dimensions[to]||!factors[from]||!factors[to])throw new Error('Unidades incompatíveis');return value*factors[from]/factors[to];}
export function preparation(drug,profile,prep,weight,stockOverride){const stock=stockOverride===undefined?profile.stock:stockOverride;if(![weight,stock,prep?.volume,prep?.amount].every(Number.isFinite)||!(weight>0)||!(stock>0)||!(prep.volume>0)||!(prep.amount>0))return null;const amount=prep.amount*(prep.perKg?weight:1);const withdrawal=amount/stock;const concentration=amount/prep.volume;if(![amount,withdrawal,concentration].every(Number.isFinite))return null;const errors=[];if(withdrawal>prep.volume+1e-9)errors.push('O volume do medicamento excede o volume final; selecione outra diluição.');if(profile.maxConcentration&&concentration>profile.maxConcentration+1e-9)errors.push('Concentração acima do limite desta referência. Selecione outra diluição.');if(profile.minConcentration&&concentration<profile.minConcentration-1e-9)errors.push('Concentração abaixo do limite desta referência.');return {amount,volume:prep.volume,withdrawal,diluentVolume:prep.volume-withdrawal,concentration,stock,errors};}
export function pumpRate(drug,rate,dose,weight,conc){if(![weight,conc,dose].every(Number.isFinite)||!(weight>0)||!(conc>0)||!(dose>=0))return null;const [unit,...parts]=rate.unit.split('/');let quantity=convert(dose,unit,drug.unit);if(parts.includes('kg'))quantity*=weight;if(parts.includes('min'))quantity*=60;if(parts.includes('day'))quantity/=24;if(rate.capPerHour!=null)quantity=Math.min(quantity,rate.capPerHour);const result=quantity/conc;return Number.isFinite(result)?result:null;}
export function reverseDose(drug,rate,pump,weight,conc){if(![weight,conc,pump].every(Number.isFinite)||!(weight>0)||!(conc>0)||!(pump>=0))return null;let quantity=pump*conc;const [unit,...parts]=rate.unit.split('/');if(parts.includes('min'))quantity/=60;if(parts.includes('day'))quantity*=24;if(parts.includes('kg'))quantity/=weight;const result=convert(quantity,drug.unit,unit);return Number.isFinite(result)?result:null;}
export function bolusResult(drug,b,weight){if(!(weight>0))return null;const dose=x=>Math.min(b.cap??Infinity,Math.max(b.minimum??0,x*(b.perKg?weight:1)));const min=dose(b.min),max=dose(b.max??b.min);const concentration=b.concentration;const unitDose=convert(max,b.unit,drug.unit);let time=b.time;if(b.maxRate)time=Math.max(time??0,max/b.maxRate);return {min,max,volumeMin:concentration?convert(min,b.unit,drug.unit)/concentration:null,volumeMax:concentration?unitDose/concentration:null,time,pump:concentration&&time?unitDose/concentration*60/time:null};}
export function getDrug(id){return DRUGS.find(d=>d.id===id);}
export function ageYears(context){if(context.profile==='ped')return context.ageMonths==null?null:context.ageMonths/12;if(context.profile==='adult')return context.ageYears??null;return context.postnatalDays==null?null:context.postnatalDays/365.25;}
export function pma(context){return context.gestWeeks==null||context.postnatalDays==null?null:context.gestWeeks+((context.gestDays??0)+context.postnatalDays)/7;}
export function getProfile(drug,context){const original=drug.profiles[context.profile];if(!original)return null;const p={...original,rates:[...(original.rates??[])],preps:[...(original.preps??[])],boluses:[...(original.boluses??[])]};if(p.resolve)return p.resolve(p,context);return p;}

