const epo=add('epoprostenol','Epoprostenol','Vasoativos','ng','Prostaciclina: vasodilatação pulmonar e inibição plaquetária.','Hipertensão arterial pulmonar especializada; uso inalatório de resgate é off-label.','Hipotensão, rubor, sangramento e rebote grave se infusão interrompida.','Diluente, pH, estabilidade e sistema dependem do produto (Flolan/Veletri). Não usar uma diluição genérica nem interromper abruptamente.',[{label:'CIDD · Epoprostenol',url:SOURCES.cidd.url}],{sources:[],reference:'Regime específico do produto e do centro de HAP. Continuidade de infusão crônica é urgente; conferir bomba/linha com equipe. Sem receita BIC genérica.'},{tag:'Protocolo específico'});epo.profiles.ped={sources:['cidd'],reference:'CIDD: início 0,5–2 ng/kg/min em diluente próprio do fabricante, com titulação especializada. Diluição, estabilidade e apresentação variam; consultar protocolo antes do preparo.'};
