export function thrombolysis(kind,context){const w=context.weight;if(!(w>0))return null;if(kind==='tenecteplase'){if(context.ageYears==null)return {error:'Informe idade e confirme STEMI para definir a dose.'};const full=w<60?30:w<70?35:w<80?40:w<90?45:50;const dose=context.ageYears>=75?full/2:full;return {label:'STEMI · '+(context.ageYears>=75?'meia dose ≥75 anos':'dose padrão'),stages:[{name:'Bolus IV em 5–10 s',dose,volume:dose/5}],total:dose,note:'Não aplicar esta dose ao AVC. Fibrinólise somente após conferência de elegibilidade.'};}if(kind==='alteplase'){const type=context.thrombolysis;if(!type)return {error:'Selecione a indicação adulta (AVC, TEP ou IAM) antes de calcular.'};if(type==='stroke'){const total=Math.min(.9*w,90);return {label:'AVC isquêmico · elegibilidade confirmada',total,stages:[{name:'Bolus em 1 min',dose:total*.1,volume:total*.1,pump:total*.1*60},{name:'Restante em 60 min',dose:total*.9,volume:total*.9,pump:total*.9}]};}if(type==='pe')return {label:'TEP adulto de alto risco · bula Activase',total:100,stages:[{name:'Infusão durante 2 h',dose:100,volume:100,pump:50}]};const a=w>=67?50:Math.min(.75*w,50),b=w>=67?35:Math.min(.5*w,35);return {label:'IAM · esquema acelerado Activase (limiar 67 kg)',total:15+a+b,stages:[{name:'Bolus',dose:15,volume:15},{name:'Próximos 30 min',dose:a,volume:a,pump:a*2},{name:'Próximos 60 min',dose:b,volume:b,pump:b}],note:'Actilyse BR pode usar limiar de 65 kg; esta calculadora identifica explicitamente a bula adotada.'};}return null;}

