for(const [clearance,dose] of [[5,.20],[10,.23],[20,.28],[30,.33],[40,.38],[50,.43]])milrinoneAdult.profiles.adult.rates.push(R(`Ajuste renal adulto · ClCr ${clearance} mL/min/1,73 m²`,dose,dose,'mcg/kg/min','Tabela da bula DailyMed; selecionar ClCr verificada, titular à resposta. Não extrapolar para diálise/CRRT, lesão renal instável ou pediatria.'));
milrinoneAdult.care+=' Monitorar ECG, PA, perfusão, diurese, creatinina e K/Mg. Furosemida precipita na linha da milrinona: não administrar pela mesma linha.';

